WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type='note' AND v.entity_id=(SELECT id FROM public.gk_notes WHERE canonical_hash='8440dc70985b652435cef7cc031fb9c4e5425bf1c6c15f7a8f2b821c0880a5be' LIMIT 1) AND v.claim_text='The source’s War on Terror, Afghanistan, Iraq, Grenada, and doctrine claims are withheld rather than rendered as unqualified learning facts.');
